/*GIONG-VIET-BAT*/
const GIONG_VIET = {"Chào mừng các bạn đến với Hành trình khám phá Tự nhiên và Xã hội!": "data:audio/mpeg;base64,", "Các bạn được ba sao! Giỏi quá!": "data:audio/mpeg;base64,", "Các bạn được hai sao! Cố lên nữa nhé!": "data:audio/mpeg;base64,", "Các bạn được một sao! Mình cùng ôn lại nhé!": "data:audio/mpeg;base64,", "Mình cùng ôn lại bài nhé!": "data:audio/mpeg;base64,", "Chưa đúng rồi, các bạn thử lại nhé!": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Đảo Mái Ấm!": "data:audio/mpeg;base64,", "Gia đình bạn Hoa có những ai? A. Ông bà, bố mẹ, Hoa và em trai. B. Chỉ có bố mẹ và Hoa. C. Cô giáo và các bạn.": "data:audio/mpeg;base64,", "Gia đình Hoa có ông bà, bố mẹ, Hoa và em trai.": "data:audio/mpeg;base64,", "Trong gia đình, mọi người yêu thương, chăm sóc lẫn nhau. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Gia đình có ông bà, cha mẹ, anh chị em; mọi người yêu thương, chăm sóc lẫn nhau.": "data:audio/mpeg;base64,", "Nhà ở là nơi sinh sống của mọi người trong gia đình. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Nhà ở là nơi sinh sống của mọi người trong gia đình.": "data:audio/mpeg;base64,", "Xếp đồ dùng vào các phòng cho phù hợp.": "data:audio/mpeg;base64,", "Gối ở phòng ngủ, chảo ở bếp, bàn chải và khăn tắm ở phòng tắm, ghế sô-pha ở phòng khách.": "data:audio/mpeg;base64,", "Mở từng ô và đoán: đây là đồ dùng gì? A. Tủ lạnh. B. Ti vi. C. Giường ngủ.": "data:audio/mpeg;base64,", "Đó là cái tủ lạnh — đồ dùng để giữ thức ăn tươi lâu.": "data:audio/mpeg;base64,", "Căn phòng nào gọn gàng hơn? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Phòng thứ hai gọn gàng hơn. Cần giữ vệ sinh và sắp xếp đồ dùng gọn gàng.": "data:audio/mpeg;base64,", "Đồ dùng nào sắc nhọn, có thể gây nguy hiểm? A. Con dao. B. Cái gối. C. Quyển sách.": "data:audio/mpeg;base64,", "Dao là đồ dùng sắc nhọn. Các bạn hãy cẩn thận với đồ dùng sắc nhọn nhé!": "data:audio/mpeg;base64,", "Cách cắm phích điện nào đúng? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Hình thứ ba đúng: lau khô tay rồi cầm vào phần nhựa của phích cắm.": "data:audio/mpeg;base64,", "Em của Hoa bị bỏng. Cần làm gì? A. Để vết bỏng dưới vòi nước mát và báo ngay cho người lớn. B. Lấy tay xoa thật mạnh vào chỗ bỏng. C. Giấu đi, không nói với ai.": "data:audio/mpeg;base64,", "Cần để vết bỏng dưới vòi nước mát và gọi ngay cho người lớn giúp đỡ.": "data:audio/mpeg;base64,", "Bạn trai trong hình đang làm việc an toàn. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Chọc vật vào ổ điện rất nguy hiểm. Nhớ sử dụng đồ dùng an toàn và đúng cách.": "data:audio/mpeg;base64,", "Bạn gái cho bạn mượn bút là biết giúp đỡ bạn bè. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Ở lớp, các bạn biết giúp đỡ nhau.": "data:audio/mpeg;base64,", "Nối mỗi người trong trường với công việc của họ.": "data:audio/mpeg;base64,", "Cô giáo dạy học, nhân viên y tế chăm sóc sức khoẻ, cô thư viện cho mượn sách, bác bảo vệ trông coi cổng trường.": "data:audio/mpeg;base64,", "Đâu là thư viện của trường? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Thư viện có nhiều giá sách để các bạn mượn sách đọc.": "data:audio/mpeg;base64,", "Trò chơi nào an toàn, trò chơi nào không an toàn?": "data:audio/mpeg;base64,", "Nhảy dây, ô ăn quan, cướp cờ là trò chơi an toàn. Trèo cây, trượt tay vịn cầu thang rất nguy hiểm.": "data:audio/mpeg;base64,", "Các bạn úp cốc xuống để giữ vệ sinh. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Cùng giữ cho trường, lớp luôn sạch đẹp.": "data:audio/mpeg;base64,", "Vẽ lên tường lớp học là việc nên làm. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Bạn đừng vẽ lên tường. Cùng giữ cho trường, lớp luôn sạch đẹp.": "data:audio/mpeg;base64,", "Các bạn trong hình đang làm gì? A. Té nước, nghịch nước — không nên. B. Rửa tay đúng cách — nên làm. C. Tưới cây giúp trường.": "data:audio/mpeg;base64,", "Các bạn đang nghịch nước, dễ trơn ngã và lãng phí nước. Không nên làm như vậy.": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Đảo Xóm Làng!": "data:audio/mpeg;base64,", "Bức tranh Minh về thăm quê có những gì? A. Trạm y tế, bưu điện, chợ, cánh đồng. B. Siêu thị, rạp chiếu phim, toà nhà cao. C. Biển, tàu thuỷ, hòn đảo.": "data:audio/mpeg;base64,", "Quê của Minh có trạm y tế, bưu điện, chợ, cánh đồng lúa, trường học.": "data:audio/mpeg;base64,", "Cảnh nào trong tranh làng quê, cảnh nào trong tranh thành phố?": "data:audio/mpeg;base64,", "Mỗi nơi sống có những quang cảnh khác nhau. Yêu quý, gắn bó với nơi mình sống nhé!": "data:audio/mpeg;base64,", "Nối mỗi người với công việc của họ.": "data:audio/mpeg;base64,", "Bác sĩ khám bệnh, chú lính cứu hoả chữa cháy, đầu bếp nấu ăn, chú cảnh sát điều khiển giao thông.": "data:audio/mpeg;base64,", "Xếp các tranh theo đúng thứ tự: từ cây lúa đến bát cơm.": "data:audio/mpeg;base64,", "Nhờ bác nông dân trồng lúa mà chúng ta có gạo để ăn. Công việc nào cũng có ích.": "data:audio/mpeg;base64,", "Bất kì công việc nào đem lại lợi ích cho xã hội đều đáng quý. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Bất kì công việc nào đem lại lợi ích cho xã hội đều đáng quý.": "data:audio/mpeg;base64,", "Tết âm lịch còn được gọi là gì? A. Tết Nguyên đán hay Tết cổ truyền. B. Tết Trung thu. C. Ngày khai giảng.": "data:audio/mpeg;base64,", "Tết âm lịch còn gọi là Tết Nguyên đán hay Tết cổ truyền.": "data:audio/mpeg;base64,", "Mở từng ô và đoán: gia đình Hoa đang làm gì để chuẩn bị Tết? A. Gói bánh chưng. B. Trồng cây. C. Đi học.": "data:audio/mpeg;base64,", "Cả nhà đang gói bánh chưng đón Tết.": "data:audio/mpeg;base64,", "Hai bức tranh nói về ngày tết nào dành cho thiếu nhi? A. Tết Trung thu. B. Tết Nguyên đán. C. Ngày Nhà giáo.": "data:audio/mpeg;base64,", "Tết Trung thu là ngày tết dành cho thiếu nhi: rước đèn, phá cỗ dưới trăng.": "data:audio/mpeg;base64,", "Nối mỗi đèn tín hiệu với ý nghĩa của nó.": "data:audio/mpeg;base64,", "Đèn xanh: được đi. Đèn vàng: giảm tốc độ. Đèn đỏ: dừng lại.": "data:audio/mpeg;base64,", "Nối mỗi biển báo với tên của nó.": "data:audio/mpeg;base64,", "Nhớ tuân thủ đèn tín hiệu và biển báo giao thông.": "data:audio/mpeg;base64,", "Biển nào cảnh báo phía trước có trẻ em? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Biển có hình hai bạn nhỏ là biển cảnh báo phía trước có trẻ em.": "data:audio/mpeg;base64,", "Các bạn trong hình đang làm gì? Có an toàn không? A. Lội qua dòng nước — không an toàn. B. Đi trên vỉa hè — an toàn. C. Qua đường ở vạch kẻ — an toàn.": "data:audio/mpeg;base64,", "Lội qua dòng nước rất nguy hiểm, dễ bị ngã, bị nước cuốn.": "data:audio/mpeg;base64,", "Đi bộ trên vỉa hè; sang đường nơi có vạch dành cho người đi bộ. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Đi bộ trên vỉa hè hoặc sát mép đường bên phải. Sang đường nơi có vạch dành cho người đi bộ.": "data:audio/mpeg;base64,", "Ngồi sau xe máy, em cần cài mũ bảo hiểm cẩn thận. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Con nhớ cài mũ cẩn thận nhé!": "data:audio/mpeg;base64,", "Xếp các bức tranh vào đúng nội dung.": "data:audio/mpeg;base64,", "Tranh nhà và cánh đồng: quang cảnh. Tranh qua đường: giao thông. Tranh nhổ khoai: công việc. Tranh hoa đào, dưa hấu: lễ hội Tết.": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Đảo Xanh Tươi!": "data:audio/mpeg;base64,", "Gắn tên các bộ phận của cây vào đúng chữ a, b, c, d, e.": "data:audio/mpeg;base64,", "a là hoa, b là lá, c là quả, d là thân, e là rễ.": "data:audio/mpeg;base64,", "Cây thường có các bộ phận: rễ, thân, lá, hoa và quả. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Có nhiều loại cây. Cây thường có rễ, thân, lá, hoa và quả.": "data:audio/mpeg;base64,", "Xếp các cây vào đúng nhóm.": "data:audio/mpeg;base64,", "Cây được trồng để cho bóng mát, làm cảnh, làm thức ăn, lấy gỗ…": "data:audio/mpeg;base64,", "Cây cần gì để lớn lên? A. Nước, không khí, ánh sáng và chất dinh dưỡng. B. Chỉ cần bóng tối. C. Không cần gì cả.": "data:audio/mpeg;base64,", "Cây cần nước, không khí, ánh sáng và chất dinh dưỡng để lớn lên.": "data:audio/mpeg;base64,", "Hạt gieo xuống đất rồi nảy mầm. Xếp đúng thứ tự mọc.": "data:audio/mpeg;base64,", "Sau khi hạt được gieo xuống đất, rễ sẽ mọc trước, rồi đến thân và lá.": "data:audio/mpeg;base64,", "Việc làm nào nên, việc làm nào không nên với cây?": "data:audio/mpeg;base64,", "Cây cần được chăm sóc và bảo vệ: tưới nước, nhổ cỏ, vun đất, bắt sâu…": "data:audio/mpeg;base64,", "Bạn nào đang chăm sóc cây đúng cách? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Bạn đang vun gốc cây là chăm sóc cây. Bẻ cành, đốt lửa dưới gốc cây là không nên.": "data:audio/mpeg;base64,", "Cây xương rồng có gai, em có thể sờ tay thoải mái. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Hãy cẩn thận khi tiếp xúc với các cây có độc và có gai.": "data:audio/mpeg;base64,", "Phần lớn các con vật đều có những bộ phận nào? A. Đầu, thân và cơ quan di chuyển. B. Rễ, thân và lá. C. Hoa và quả.": "data:audio/mpeg;base64,", "Phần lớn các con vật đều có đầu, thân và cơ quan di chuyển.": "data:audio/mpeg;base64,", "Con vật di chuyển bằng cách nào? Hãy nối.": "data:audio/mpeg;base64,", "Con ong bay, con ếch nhảy, con cá bơi.": "data:audio/mpeg;base64,", "Đố bạn: Con gì tám cẳng hai càng? Mở ô để kiểm tra. A. Con cua. B. Con cá. C. Con gà.": "data:audio/mpeg;base64,", "Đó là con cua: tám cẳng, hai càng.": "data:audio/mpeg;base64,", "Con vật nào có ích, con vật nào gây hại cho con người?": "data:audio/mpeg;base64,", "Các con vật có nhiều lợi ích như làm thức ăn, lấy sức kéo… nhưng một số con vật gây hại cho con người.": "data:audio/mpeg;base64,", "Chúng ta ngủ màn để không bị muỗi đốt. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Muỗi gây hại cho con người, cần ngủ màn.": "data:audio/mpeg;base64,", "Việc làm nào KHÔNG nên làm với vật nuôi? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Không nên trêu chó, dễ bị cắn. Đưa mèo đi khám, rửa chuồng là chăm sóc vật nuôi.": "data:audio/mpeg;base64,", "Khi bị chó, mèo cắn, em cần làm gì? A. Rửa vết thương, báo người lớn và đi tiêm phòng. B. Không nói với ai. C. Đánh lại con vật.": "data:audio/mpeg;base64,", "Rửa sạch vết thương dưới vòi nước, báo ngay người lớn và đi tiêm phòng.": "data:audio/mpeg;base64,", "Ôm chặt làm mèo đau là cách chơi an toàn với mèo. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Làm mèo đau, nó sẽ cào đấy. Hãy cẩn thận, không để con vật cào, cắn.": "data:audio/mpeg;base64,", "Chào mừng các bạn đến với Đảo Bầu Trời!": "data:audio/mpeg;base64,", "Bộ phận nào – làm việc gì? Kéo việc vào đúng chữ.": "data:audio/mpeg;base64,", "Đầu để suy nghĩ, cổ giúp quay đầu, tay để cầm nắm, chân để đi.": "data:audio/mpeg;base64,", "Nối mỗi giác quan với việc nó giúp em làm.": "data:audio/mpeg;base64,", "Năm giác quan: mắt, mũi, lưỡi, tai và da giúp em nhận biết mọi vật xung quanh.": "data:audio/mpeg;base64,", "Em dùng giác quan nào để nhận biết các vật trong hình? A. Tai. B. Mũi. C. Lưỡi.": "data:audio/mpeg;base64,", "Tiếng gà gáy, tiếng trống, tiếng còi xe: em nghe bằng tai.": "data:audio/mpeg;base64,", "Em dùng giác quan nào để nhận biết mùi của các vật này? A. Mắt. B. Mũi. C. Tai.": "data:audio/mpeg;base64,", "Mùi thơm của hoa hồng, xà phòng, nước hoa: em ngửi bằng mũi.": "data:audio/mpeg;base64,", "Việc nào nên, việc nào không nên để bảo vệ mắt và tai?": "data:audio/mpeg;base64,", "Luôn chăm sóc và bảo vệ các giác quan nhé!": "data:audio/mpeg;base64,", "Bạn nào đang bảo vệ da khi trời nắng? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Che ô khi trời nắng giúp bảo vệ da.": "data:audio/mpeg;base64,", "Một ngày, bạn Minh ăn những bữa nào? A. Bữa sáng, bữa trưa và bữa tối. B. Chỉ ăn bữa tối. C. Chỉ ăn bữa sáng.": "data:audio/mpeg;base64,", "Minh ăn ba bữa: bữa sáng, bữa trưa ở trường và bữa tối cùng gia đình.": "data:audio/mpeg;base64,", "Việc nào nên, việc nào không nên khi ăn, uống?": "data:audio/mpeg;base64,", "Ăn, uống đầy đủ, an toàn giúp cơ thể khoẻ mạnh và phòng tránh bệnh tật.": "data:audio/mpeg;base64,", "Em chọn thức ăn nào an toàn? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Bánh mì còn hạn sử dụng là an toàn. Cam bị mốc, ngô có ruồi đậu thì không nên ăn.": "data:audio/mpeg;base64,", "Hoạt động nào là nghỉ ngơi KHÔNG hợp lí? Các bạn chọn tranh A, B, C.": "data:audio/mpeg;base64,", "Xem ti vi đến tối muộn là không hợp lí. Vận động và nghỉ ngơi hợp lí giúp cơ thể khoẻ mạnh.": "data:audio/mpeg;base64,", "Không được cho người khác chạm vào miệng, ngực, giữa hai đùi và mông của mình. Đúng hay sai?": "data:audio/mpeg;base64,", "Đúng rồi! Đó là những vùng riêng tư cần được bảo vệ.": "data:audio/mpeg;base64,", "Hành động nào an toàn, hành động nào không an toàn?": "data:audio/mpeg;base64,", "Bố ôm con, mẹ tắm cho con, bác sĩ khám khi có bố mẹ bên cạnh là an toàn. Người lạ kéo tay, bị bắt nạt, bị đá là không an toàn.": "data:audio/mpeg;base64,", "Khi gặp tình huống không an toàn, em có thể làm gì? A. Gọi điện cho bố mẹ hoặc gọi tổng đài 111. B. Im lặng, không nói với ai. C. Đi theo người lạ.": "data:audio/mpeg;base64,", "Hãy đi cùng bố mẹ, bạn bè; gọi người lớn khi cần giúp đỡ. Có thể gọi tổng đài 111.": "data:audio/mpeg;base64,", "Vào ban đêm, em có thể nhìn thấy gì trên bầu trời? A. Mây, Mặt Trăng và các vì sao. B. Mặt Trời chói chang. C. Cầu vồng.": "data:audio/mpeg;base64,", "Ban ngày nhìn thấy mây và Mặt Trời; ban đêm nhìn thấy mây, Mặt Trăng và các vì sao.": "data:audio/mpeg;base64,", "Hoạt động nào diễn ra vào ban ngày, ban đêm?": "data:audio/mpeg;base64,", "Đi học, vui chơi ngoài trời vào ban ngày. Học bài buổi tối và đi ngủ vào ban đêm.": "data:audio/mpeg;base64,", "Em có thể nhìn thẳng vào Mặt Trời. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Không được nhìn trực tiếp vào Mặt Trời. Nhớ đội mũ, nón khi đi dưới trời nắng.": "data:audio/mpeg;base64,", "Hình nào cho biết trời có gió? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Lá cờ bay phấp phới, chong chóng quay: trời có gió.": "data:audio/mpeg;base64,", "Chọn đồ dùng phù hợp với thời tiết.": "data:audio/mpeg;base64,", "Cần theo dõi dự báo thời tiết để lựa chọn trang phục phù hợp.": "data:audio/mpeg;base64,", "Thời tiết nào chúng ta KHÔNG nên ra ngoài? Các bạn chọn tranh A, B.": "data:audio/mpeg;base64,", "Trời giông bão, mưa to, gió mạnh thì không nên ra ngoài.": "data:audio/mpeg;base64,", "Trú mưa dưới gốc cây to khi có sấm sét là an toàn. Đúng hay sai?": "data:audio/mpeg;base64,", "Sai rồi! Khi có sấm sét, không đứng trú dưới gốc cây to.": "data:audio/mpeg;base64,"};
let __amDang = null, __giongMay = null;
function __chuanGiong(t){ return String(t).normalize("NFC").replace(/\s+/g, " ").trim(); }
function __choDeNghe(t){
  const doi = [["π"," pi "],["cm³"," xăng-ti-mét khối"],["cm²"," xăng-ti-mét vuông"],["dm³"," đề-xi-mét khối"],["m³"," mét khối"],
    ["m²"," mét vuông"],["×"," nhân "],["÷"," chia "],["−"," trừ "],["≈"," xấp xỉ "],["="," bằng "],["+"," cộng "]];
  t = String(t).replace(/<[^>]+>/g, "");
  for (const [a, b] of doi) t = t.split(a).join(b);
  return __chuanGiong(t.replace(/(\d)\s*cm\b/g, "$1 xăng-ti-mét").replace(/(\d)\s*m\b/g, "$1 mét"));
}
function __timGiongMay(){ try { const ds = speechSynthesis.getVoices().filter(v => /^vi/i.test(v.lang));
  __giongMay = ds.find(v => /Natural|Online|HoaiMy|Hoài/i.test(v.name)) || ds[0] || null; } catch(e){} return __giongMay; }
try { if (window.speechSynthesis){ __timGiongMay(); speechSynthesis.addEventListener("voiceschanged", __timGiongMay); } } catch(e){}
function coGiongViet(chu){ return !!(GIONG_VIET[__chuanGiong(chu)] || __giongMay || __timGiongMay()); }
function dungGiong(){ try { if (__amDang){ __amDang.pause(); __amDang = null; } if (window.speechSynthesis) speechSynthesis.cancel(); } catch(e){} }
function __baoChuaCoGiong(){ try { if (document.getElementById("__baoGiong")) return; const d = document.createElement("div"); d.id = "__baoGiong";
  d.setAttribute("role", "status");
  d.textContent = "Máy chưa có giọng đọc tiếng Việt cho câu này. Mở bằng Microsoft Edge (có mạng) để nghe giọng Việt, hoặc cài thêm giọng Tiếng Việt: Cài đặt Windows → Thời gian và ngôn ngữ → Giọng nói.";
  d.style.cssText = "position:fixed;left:50%;bottom:18px;transform:translateX(-50%);max-width:92vw;background:#1f2937;color:#fff;padding:12px 16px;border-radius:12px;font:15px/1.4 system-ui,sans-serif;z-index:99999;box-shadow:0 6px 20px rgba(0,0,0,.3)";
  document.body.appendChild(d); setTimeout(() => d.remove(), 7000); } catch(e){} }
function __docMay(chu, toc){
  if (!__giongMay){ __baoChuaCoGiong(); return; }   // KHÔNG có giọng Việt → báo, không đọc bằng giọng Anh
  const u = new SpeechSynthesisUtterance(chu); u.voice = __giongMay; u.lang = __giongMay.lang; u.rate = toc || 0.9; speechSynthesis.speak(u);
}
function docGiongViet(goc, chuMay, toc){
  dungGiong(); const k = __chuanGiong(goc);
  if (GIONG_VIET[k]){ try { __amDang = new Audio(GIONG_VIET[k]); const h = __amDang.play(); if (h && h.catch) h.catch(() => {}); return; } catch(e){} }
  try { if (!window.speechSynthesis){ __baoChuaCoGiong(); return; }
    const chu = chuMay || __choDeNghe(goc);
    if (!__giongMay && !__timGiongMay() && !speechSynthesis.getVoices().length){   // Chrome nạp danh sách giọng chậm
      setTimeout(() => { __timGiongMay(); __docMay(chu, toc); }, 700); return; }
    __docMay(chu, toc); } catch(e){}
}
/*GIONG-VIET-HET*/